162: async function fetchPointElevationMeters(lngLat: LngLat, signal: AbortSignal): Promise<number | null> {
163:   const [lng, lat] = lngLat;
164:   const url = `https://api.open-meteo.com/v1/elevation?latitude=${lat}&longitude=${lng}`;
165:   const response = await fetch(url, { signal });
166:   if (!response.ok) return null;
167:   const data = (await response.json()) as { elevation?: number[] };
168:   const v = data.elevation?.[0];
169:   return typeof v === "number" && Number.isFinite(v) ? v : null;
170: }
