704:   function applyDistanceDirectionMode(checked: boolean) {
705:     distanceDirectionChecked = checked;
706:     /*
707:      * 브리지는 **그때그때 다시 찾는다**(2026-09-18 Chief).
708:      * `mapBridge` 는 팝업을 만들 때 한 번 잡아 둔 값이라, 그 시점에 아직 등록 전이었거나
709:      * 이후 다시 등록됐으면 `null`·낡은 객체를 붙들고 있다 — 그러면 이 호출이 조용히
710:      * 사라져 체크를 풀어도 훅은 아무것도 모른다(반경 원이 그대로 남던 원인).
711:      *
712:      * 지시30 — 경로는 하나로 유지. 체크에 따라 패널 접기만 함께 바꾸고(UI),
713:      * 수동 경로 준비/토큰 disabled 가 낡지 않게 syncProfileUi 도 갱신한다.
714:      * 핀·거리 값·탐색 콜백은 여기서 건드리지 않는다(아래 정리 호출 제외).
715:      */
716:     getDistanceAutoRouteMapBridge()?.setDistanceDirectionMode?.(checked);
717:     if (checked) {
718:       routeDistanceExpanded = true;
719:       routeLocationExpanded = false;
720:     } else {
721:       routeLocationExpanded = true;
722:       routeDistanceExpanded = false;
723:     }
724:     syncDistanceModeUi();
725:     syncRouteLocationPanel();
726:     syncRouteDistancePanel();
727:     syncProfileUi();
728:     if (!checked) {
729:       onClearAutoRouteClickDebugMarker?.();
730:       // 원을 소유한 쪽에 직접 지우라고 말한다 — 훅의 정리에만 기대지 않는다.
731:       onClearDistanceAutoRouteCircle?.();
732:       setInlinePhase("idle");
733:       return;
734:     }
735:     previewCircleForTargetKm(targetKm);
736:     tryArmDirectionPickIfChecked();
737:   }
