744:   function stepTargetKm(deltaKm: number) {
745:     if (!distanceDirectionChecked) return;
746:     const next = Math.min(
747:       DISTANCE_AUTO_ROUTE_KM_MAX,
748:       Math.max(
749:         DISTANCE_AUTO_ROUTE_KM_MIN,
750:         Math.round((targetKm + deltaKm) / DISTANCE_AUTO_ROUTE_KM_STEP) * DISTANCE_AUTO_ROUTE_KM_STEP,
751:       ),
752:     );
753:     syncDistanceInputs(next);
754:     previewCircleForTargetKm(next);
755:     tryArmDirectionPickIfChecked();
756:   }
