758:   function setInlinePhase(
759:     phase: "idle" | "direction" | "searching" | "found" | "failed",
760:     message?: string,
761:   ) {
762:     autoRouteStatus.className = "map-view__pick-auto-route-status";
763:     autoRouteStatus.dataset.phase = phase;
764:     if (phase === "idle") {
765:       autoRouteStatus.textContent = "";
766:       autoRouteStatus.classList.add("map-view__pick-auto-route-status--idle");
767:       syncRouteStatusSlot();
768:       return;
769:     }
770:     if (phase === "direction") {
771:       autoRouteStatus.textContent =
772:         message ?? formatDistanceAutoRouteDirectionClickHint(targetKm);
773:       syncRouteStatusSlot();
774:       return;
775:     }
776:     if (phase === "searching") {
777:       autoRouteStatus.classList.add("map-view__pick-auto-route-status--searching");
778:       autoRouteStatus.textContent =
779:         message ?? "목표 거리에 맞는 도로 경로를 찾는 중입니다…";
780:       syncRouteStatusSlot();
781:       return;
782:     }
783:     if (phase === "failed") {
784:       autoRouteStatus.classList.add("map-view__pick-auto-route-status--failed");
785:       autoRouteStatus.textContent = message ?? "경로를 찾지 못했습니다.";
786:       syncRouteStatusSlot();
787:       return;
788:     }
789:     autoRouteStatus.classList.add("map-view__pick-auto-route-status--found");
790:     autoRouteStatus.textContent = message ?? "경로를 찾았습니다.";
791:     syncRouteStatusSlot();
792:   }
