794:   function tryArmDirectionPick() {
795:     if (!distanceDirectionChecked) return;
796:     const start = getRouteStart();
797:     if (!start || typeof onArmDirectionPick !== "function") return;
798:     if (getRouteTokenInsufficient?.()) {
799:       setInlinePhase("failed", ROUTE_TOKEN_INSUFFICIENT_HINT);
800:       return;
801:     }
802:     const parsed = Number.parseFloat(distanceNumber.value);
803:     const validated = validateDistanceAutoRouteTargetKm(parsed);
804:     if (!validated.ok) {
805:       setInlinePhase("failed", validated.message);
806:       return;
807:     }
808:     syncDistanceInputs(validated.km);
809:     previewCircleForTargetKm(validated.km);
810:     const result = onArmDirectionPick({
811:       start,
812:       profile: currentProfile,
813:       targetKm: validated.km,
814:     });
815:     if (!result.ok) {
816:       setInlinePhase("failed", result.message);
817:       return;
818:     }
819:     autoSessionActive = true;
820:     const rerouteReady = autoRouteStatus.dataset.phase === "found";
821:     setInlinePhase(
822:       "direction",
823:       rerouteReady || autoRouteStatusMessage === DISTANCE_AUTO_ROUTE_REROUTE_HINT
824:         ? DISTANCE_AUTO_ROUTE_REROUTE_HINT
825:         : formatDistanceAutoRouteDirectionClickHint(validated.km),
826:     );
827:     onDirectionPickArmed?.();
828:   }
