.map-view__pick-route-toolbar {
  display: flex;
  flex-wrap: nowrap;
  align-items: stretch;
  gap: 0.24rem;
  min-width: 0;
  max-width: 100%;
  margin-top: 0.14rem;
}

.map-view__pick-route-toolbar .map-view__pick-route-toggle {
  flex: 1 1 0;
  width: auto;
  min-width: 0;
  min-height: 44px;
}

.map-view__pick-route-panel--location {
  margin-top: 0.06rem;
}

